#include <iostream>
#include <string>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string P, A;
    if (!(cin >> P >> A)) return 0;

    vector<int> countP(26, 0);
    vector<int> countA(26, 0);

    for (char c : P) {
        countP[c - 'a']++;
    }

    for (char c : A) {
        if (c != '*') {
            countA[c - 'a']++;
        }
    }

    bool possible = true;
    for (int i = 0; i < 26; ++i) {
        if (countA[i] > countP[i]) {
            possible = false;
            break;
        }
    }

    if (possible) {
        cout << "S\n";
    } else {
        cout << "N\n";
    }

    return 0;
}
